def compact(n: int) -> str:
    if n < 1000:
        return f"{n:.1f}".replace('.', ',').rstrip('0') or '0'

    # Try mil, mi, bi units in order and pick the one after rounding
    for divisor, unit in [(1000, 'mil'), (1000000, 'mi'), (1000000000, 'bi')]:
        value = n / divisor
        rounded = round(value, 1)
        if rounded >= 1:
            result = f"{rounded:.1f}"
            if result.endswith(',0'):
                result = result[:-2]
            return f"{result} {unit}"

    # Should not be reached for non-negative integers
    return str(n)
