from decimal import Decimal

def reached(value, threshold):
    def normalize(num):
        if isinstance(num, bool):
            raise TypeError("bool cannot be used for comparison in reached")
        if isinstance(num, (int, float)):
            # Convert int or float to Decimal using its shortest exact decimal form
            return Decimal(str(num))
        if isinstance(num, Decimal):
            return num
        raise TypeError(f"Unsupported type: {type(num).__name__}")

    value_normalized = normalize(value)
    threshold_normalized = normalize(threshold)

