from datetime import date, timedelta

def add_business_days(d: date, n: int, holidays: set[date]) -> date:
    def is_business_day(date_obj: date) -> bool:
        return date_obj.weekday() < 5 and date_obj not in holidays

    current = d + timedelta(days=0)
    days_to_move = n

    # Special case: n == 0
    if n == 0:
        if is_business_day(d):
            return d

    # Determine direction and starting point
    if n > 0:
        candidate = d + timedelta(days=1)
        while days_to_move > 0:
            if is_business_day(candidate):
                days_to_move -= 1
                current = candidate
            candidate += timedelta(days=1)
    else:  # n < 0
        candidate = d - timedelta(days=1)
        while days_to_move < 0:
            if is_business_day(candidate):
                days_to_move += 1
                current = candidate
            candidate -= timedelta(days=1)

    return current
