def compare_versions(a: str, b: str) -> int:
    def parse_version(version: str):
        # Build metadata after '+' is ignored
        version = version.split('+')[0]

        # Split into base and pre-release
        if '-' in version:
            base, prerelease_str = version.split('-', 1)
        else:
            base, prerelease_str = version, None

        # Parse major.minor.patch
        segments = base.split('.')
        major = int(segments[0]) if len(segments) >= 1 else 0
        minor = int(segments[1]) if len(segments) >= 2 else 0
        patch = int(segments[2]) if len(segments) >= 3 else 0

        # Parse pre-release identifiers dot by dot
        prerelease_ids = []
        if prerelease_str:
            for id_ in prerelease_str.split('.'):
                try:
                    prerelease_ids.append((1, int(id_)))
                except ValueError:
                    prerelease_ids.append((0, id_))

        return (major, minor, patch, prerelease_ids)

    a_parsed = parse_version(a)
    b_parsed = parse_version(b)

    major_a, minor_a, patch_a, pre_a = a_parsed
    major_b, minor_b, patch_b, pre_b = b_parsed

    if major_a != major_b:
        return 1 if major_a > major_b else -1
    if minor_a != minor_b:
        return 1 if minor_a > minor_b else -1
    if patch_a != patch_b:
        return 1 if patch_a > patch_b else -1

    def compare_prerelease(pre_list):
        for i in range(min(len(pre_list[0]), len(pre_list[1]))):
            typ_a, val_a = pre_list[0][i]
            typ_b, val_b = pre_list[1][i]
            if typ_a != typ_b:
                return 1 if typ_a > typ_b else -1
            if val_a != val_b:
                return 1 if val_a > val_b else -1

        if len(pre_list[0]) < len(pre_list[1]):
            return -1
        elif len(pre_list[0]) > len(pre_list[1]):
            return 1
        return 0

    # Pre-release is lower than release (no pre-release)
    has_pre_a = len(pre_a) > 0
    has_pre_b = len(pre_b) > 0

    if has_pre_a != has_pre_b:
        return -1 if has_pre_a else 1

    return compare_prerelease((pre_a, pre_b))
