def build_order(deps: dict[str, list[str]]) -> list[str]:
    all_items = set(deps.keys()) | set(deps.values())
    in_degree = {item: 0 for item in all_items}
    graph = {}

    for item, dependents in deps.items():
        for dep in dependents:
            graph.setdefault(dep, []).append(item)
            in_degree[item] += 1

    ready = sorted([item for item in all_items if in_degree[item] == 0])
    result = []

    while ready:
        item = ready.pop(0)
        result.append(item)

        if item in graph:
            for dependent in graph[item]:
                in_degree[dependent] -= 1
                if in_degree[dependent] == 0:
                    ready.append(dependent)
                    ready.sort()

    if len(result) != len(all_items):
        raise ValueError("Cycle detected")

    return result
