def deep_merge(base: dict, override: dict) -> dict:
    """Returns a new dict with keys from override winning over base.

    When both values are dicts, they are merged recursively.
    Lists and other values are replaced, not merged.
    An override value of None deletes the key in the result.
    Neither input is modified, and the result does not share nested dicts/lists.
    """
    if not base and not override:
        return {}

    result = {}

    all_keys = set(base.keys()) | set(override.keys())

    for key in all_keys:
        base_val = base.get(key)
        override_val = override.get(key)

        if override_val is None:
            continue
        elif isinstance(base_val, dict) and isinstance(override_val, dict):
            result[key] = deep_merge(base_val, override_val)
        else:
            result[key] = override_val

    return result
