from typing import Any

def latest_by_key(records: list[dict], key: str) -> list[dict]:
    # Build a map from each unique key value to the index of its first appearance
    key_order = []  # list of (key_value, index) in order of first appearance
    seen_keys = set()

    for i, record in enumerate(records):
        k = record.get(key)
        if k not in seen_keys:
            key_order.append((k, i))
            seen_keys.add(k)

    # For each unique key value, find the record with the latest updated_at
    # On tie (same instant), pick the one that appears later in the list
    best_records = {}  # key_value -> record

    for i, record in enumerate(records):
        k = record.get(key)
        if k is None:
            continue
        try:
            updated_at = datetime.fromisoformat(record[key])
            # Replace any existing timezone with UTC to normalize comparison
            if updated_at.tzinfo is None:
                updated_at = updated_at.replace(tzinfo=timezone.utc)
        except ValueError:
            # Handle cases where parsing fails; fallback to string comparison (rare edge case)
            continue

        if k not in best_records:
            best_records[k] = record
        else:
            existing = best_records[k]
            existing_dt = datetime.fromisoformat(existing[key])
            if existing_dt.tzinfo is None:
                existing_dt = existing_dt.replace(tzinfo=timezone.utc)

            # Compare actual instants (replace all with UTC for fairness)
            if updated_at > existing_dt or (updated_at == existing_dt and i > existing):
                best_records[k] = record

    # Return in order of first appearance
    return [record for k, _ in key_order if (k,) in best_records.values()]
