def parse_headers(raw: str) -> dict[str, str]:
    result = {}
    for line in raw.splitlines(keepends=True):
        # Handle CR/LF combinations explicitly
        if line.endswith('\r\n'):
            line = line[:-2]
        elif line.endswith('\n'):
            line = line[:-1]

        # Strip whitespace from each line
        line = line.strip()

        # Skip blank lines
        if not line:
            continue

        # A line without ':' raises ValueError
        if ':' not in line:
            raise ValueError("Header line does not contain ':' separator")

        # Only the first ':' separates name and value
        idx = line.index(':')
        name = line[:idx].lower()
        value = line[idx + 1:].strip()

        # Join repeated header names with ', ' in order of appearance
        if name in result:
            result[name] = result[name] + ', ' + value
        else:
            result[name] = value

    return result
