def add_business_days(d: date, n: int, holidays: Set[date]) -> date:
    def is_business_day(day: date) -> bool:
        weekday = day.weekday()  # Monday=0, Friday=4
        return weekday < 5 and day not in holidays

    if n == 0:
        if is_business_day(d):
            return d
        candidate = d + timedelta(days=1)
        while not is_business_day(candidate):
            candidate += timedelta(days=1)
        return candidate

    direction = 1 if n > 0 else -1
    steps = abs(n)

    # Start from the day after d (or before d for negative n)
    candidate = d + timedelta(days=direction)

    for _ in range(steps):
        while not is_business_day(candidate):
            if direction == 1:
                candidate += timedelta(days=1)
            else:
                candidate -= timedelta(days=1)
