def compare_versions(a: str, b: str) -> int:
    import re

    def parse(v):
        # Split build metadata (after '+'), ignored in comparison
        if '+' in v:
            version, _ = v.rsplit('+', 1)
        else:
            version, _ = v, ''

        # Split main version and pre-release
        if '-' in version:
            main, prerelease = version.split('-', 1)
        else:
            main, prerelease = version, None

        # Parse MAJOR.MINOR.PATCH
        parts = [int(x) for x in main.split('.')]
        return parts, prerelease

    def parse_id(identifier):
        """Parse a single pre-release identifier. Returns (is_numeric, value)."""
        if re.fullmatch(r'\d+', identifier):
            return True, int(identifier)
        else:
            return False, identifier  # alphanumeric fallback

    def cmp_ids(id_a, id_b):
        """Compare two identifiers. Numeric < alphanumeric; equal numeric values are equal."""
        na, va = parse_id(id_a)
        nb, vb = parse_id(id_b)

        if na and not nb:
            return -1  # numeric < alphanumeric
        if not na and nb:
            return 1   # alphanumeric > numeric

        if na and nb:
            # Both numeric: compare as numbers
            if va != vb:
                return -1 if va < vb else (1 if va > vb else 0)

        if not na and not nb:
            # Both alphanumeric: lexicographic comparison
            if id_a != id_b:
                return -1 if id_a < id_b else (1 if id_a > id_b else 0)

        return 0

    pa, pra_a = parse(a)
    pb, pra_b = parse(b)

    # Compare MAJOR, MINOR, PATCH
    for i in range(3):
        va = pa[i]
        vb = pb[i] if i < len(pb) else 0
        if va != vb:
            return -1 if va < vb else 1

    # If all three components are equal, compare pre-release tags
    if pra_a is None and pra_b is None:
        return 0
    if pra_a is None:
        return 1   # release > pre-release
    if pra_b is None:
        return -1 # pre-release < release

    ids_a = pra_a.split('.')
    ids_b = pra_b.split('.')

    for i in range(max(len(ids_a), len(ids_b))):
        id_a = ids_a[i] if i < len(ids_a) else ''
        id_b = ids_b[i] if i < len(ids_b) else ''

        cmp = cmp_ids(id_a, id_b)
        if cmp != 0:
            return cmp

    # All identifiers equal so far; shorter list is lower
    if len(ids_a) != len(ids_b):
        return -1 if len(ids_a) < len(ids_b) else 1

    return 0
