import heapq
from collections import defaultdict


def build_order(deps: dict[str, list[str]]) -> list[str]:
    # Collect all items: keys (with dependencies) and values (dependencies)
    all_items = set(deps.keys())
    for dep_list in deps.values():
        all_items.update(dep_list)

    # Track number of unresolved dependencies (in-degree)
    in_degree = {item: 0 for item in all_items}

    # Build the dependency graph and compute in-degrees
    for item, dependent_list in deps.items():
        for dep in dependent_list:
            if dep not in in_degree:
                in_degree[dep] = 0
            in_degree[item] += 1

    # Min-heap to process items alphabetically among those ready now
    heap = [item for item in all_items if in_degree[item] == 0]
    heapq.heapify(heap)

    result = []

    while heap:
        current = heapq.heappop(heap)
        result.append(current)

        # For each dependent of the current item, decrease its in-degree
        for item, dependent_list in deps.items():
            if current in dependent_list:
                in_degree[item] -= 1
                if in_degree[item] == 0:
                    heapq.heappush(heap, item)

    # If we didn't include all items, there was a cycle
    if len(result) != len(all_items):
        raise ValueError("Cycle detected")

    return result
