        # IPv4 check
        octets = ip.split('.')
        if len(octets) == 4:
            try:
                ints = [int(o) for o in octets]
                if all(0 <= i <= 255 for i in ints):
                    return
            except ValueError:
                pass
        # IPv6 check
        parts = ip.split(':')
        if len(parts) > 12:
            raise ValueError("Invalid IPv6 address")
        for p in parts:
            try:
                int(p, 16)
            except ValueError:
                raise ValueError(f"Invalid IP address: {ip}")

    def _validate_network(cidr: str) -> None:
        if not cidr or not isinstance(cidr, str):
            raise ValueError("Invalid network")
        if '/' not in cidr:
            raise ValueError("Invalid CIDR notation")
        prefix_len = int(cidr.split('/')[1])
        if not (0 <= prefix_len <= 128):
            raise ValueError("Invalid prefix length")

    def _ip_to_bits(ip: str, bits_per_octet: int) -> int:
        parts = ip.split('.')
        value = 0
        for p in parts:
            if not (0 <= int(p) <= 255):
                raise ValueError("Invalid IP octet")
            value = (value << bits_per_octet) | int(p)
        return value

    def _cidr_mask(prefix_len: int, total_bits: int) -> int:
        return (-1 << (total_bits - prefix_len)) & ((1 << total_bits) - 1)

