            raise ValueError("Prefix length exceeds 128 for IPv6")

        # Check address type by inspecting the network
        is_ipv4_network = '.' in net.lower() and ':' not in net.lower()
        if is_ipv4_network:
            network_bits = _ip_to_bits(net.split('/')[0], 8)
            mask = _cidr_mask(prefix_len, 32) & 0xFFFFFFFF
            ip_value = int(ip, 16) if ':' in ip else _ip_to_bits(ip, 8)
            network_base = network_bits & mask
            ip_network = ip_value & mask
            if network_base == ip_network:
