import re

def parse_duration(s: str) -> int:
    if not s or not s.strip():
        raise ValueError("Invalid or empty string")

    unit_map = {'h': 3600, 'm': 60, 's': 1}
    valid_units = set(unit_map.keys())

    pattern = r'(\d+)([hm]?)'
    matches = re.findall(pattern, s)

