from decimal import Decimal

def parse_brl(s: str) -> Decimal:
    s = s.strip()
    negative = False

    # Check for leading minus or parentheses wrapping the value
    if s.startswith('-'):
        negative = True
        s = s[1:]
    elif s.startswith('('):
        negative = True
        # Find closing parenthesis
        close_paren = s.rfind(')')
        if close_paren == -1 or close_paren <= 0:
            raise ValueError("Invalid format: unclosed parenthesis")
        s = s[:close_paren]
        if ')' in s[1:] and s.rfind(')') != close_paren:
            # There might be extra content after ) that isn't part of the value
            pass

    # Remove R$ prefix if present (with optional spaces before it)
    while s and s[0] == ' ':
        s = s[1:]
    if s.startswith('R$'):
        s = s[2:]
    while s and s[0] == ' ':
        s = s[1:]

    # Check for whitespace at end
    if s and not s.strip():
        return Decimal('0')  # Empty string after stripping -> 0

    s = s.strip()

    # Determine decimal part: look for ',' or absence of it
    if ',' in s:
        cents_parts = s.split(',')
        if len(cents_parts) != 2:
            raise ValueError("Invalid format: expected exactly one comma with cents")

        int_part_raw, cents_raw = cents_parts

        # Validate cents: must be exactly 2 digits
        if not cents_raw.isdigit() or len(cents_raw) != 2:
            raise ValueError(f"Cents must be exactly 2 digits, got '{cents_raw}'")
    else:
        int_part_raw = s
        cents_raw = ''

    # Validate integer part: either plain digits or groups of 3 with dots
    if '.' in int_part_raw:
        parts = int_part_raw.split('.')
        if len(parts) != 2:
            raise ValueError("Invalid format: too many or too few dots")
        int_groups = parts[0]
        if not int_groups.isdigit():
            raise ValueError("Invalid format: non-digit characters in integer part groups")
        # Check grouping: each group should be exactly 3 digits
        for i, g in enumerate(int_groups):
            if len(g) != 3 or not g.isdigit():
                raise ValueError("Invalid format: integer groups must be exactly 3 digits")

        cleaned_int = int_part_raw.replace('.', '')
    else:
        if not int_part_raw.isdigit():
            raise ValueError("Invalid format: non-digit characters in integer part")
        cleaned_int = int_part_raw

    # Validate cents string is empty or valid (already checked)
    if cents_raw and not cents_raw.isdigit():
        raise ValueError("Invalid format: cents must be digits only")

    total_str = cleaned_int + '.' + cents_raw
    result = Decimal(total_str)

    if negative:
        result = -result

    return result
