import re

def wrap(text: str, width: int) -> list[str]:
    # Extract words split by any whitespace, filtering empty strings
    raw_words = [w for w in re.findall(r'\S+', text)]

    # If no words, return empty list
    if not raw_words:
        return []

    # Process each word: split long ones into chunks of at most width
    processed_words = []
    for w in raw_words:
        if len(w) <= width:
            processed_words.append(w)
        else:
            # Cut the word into pieces of exactly width, last may be shorter
            chunk_count = (len(w) + width - 1) // width
            for i in range(chunk_count):
                start = i * width
                end = start + width
                processed_words.append(w[start:end])

    # Greedily build lines of at most width characters, single space between words
    lines = []
    current_line = ""

    for word in processed_words:
        if len(current_line) + 1 + len(word) <= width:
            if not current_line:
                current_line = word
            else:
                current_line += " " + word
        else:
            if current_line:
                lines.append(current_line)
            current_line = word

    # Don't forget the last line
    if current_line:
        lines.append(current_line)

    return lines
