def set_ini_value(text: str, section: str, key: str, value: str) -> str:
    lines = text.splitlines()
    result_lines = []
    current_section = None

    for line in lines:
        stripped = line.strip()

        # Check if this is a section header
        if stripped.startswith('[') and stripped.endswith(']'):
            inner_section = stripped[1:-1]
            if inner_section == section:
                current_section = section
            else:
                current_section = None
            result_lines.append(line)
            continue

        # Check for comment or blank lines - pass through unchanged
        if not stripped or stripped.startswith(';') or stripped.startswith('#'):
            result_lines.append(line)
            continue

        # If we're in the target section, find the key and update it
        if current_section == section:
            parts = line.split('=', 1)
            if len(parts) == 2:
                lhs = parts[0].strip()
                if lhs == key:
                    result_lines.append(f"{key} = {value}")
                    continue

        # Non-matching non-comment/non-blank lines pass through unchanged
        result_lines.append(line)

    return '\n'.join(result_lines)
