    best = {}  # key_value -> (timestamp, index, record)
    for i, record in enumerate(records):
        k = record[key]
        ts = parse_iso(record['updated_at'])
        if k not in best:
            best[k] = (ts, i, record)
        else:
            existing_ts, existing_i, _ = best[k]
            if ts > existing_ts or (ts == existing_ts and i > existing_i):
                best[k] = (ts, i, record)

    # Return records in order of first key appearance
    return [best[k][2] for k in key_order]
